-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.release_digest_shift(digests jsonb, tbl text, plus jsonb, minus jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_set(digests, array[tbl], jsonb_build_array(
           (digests -> tbl ->> 0)::numeric + (plus ->> 0)::numeric - (minus ->> 0)::numeric,
           (digests -> tbl ->> 1)::numeric + (plus ->> 1)::numeric - (minus ->> 1)::numeric));
$function$;
